insert into public.capelas (id, num, slug, name, padroeiro, zona, localidade, ano, festa, estilo, conservacao, guardiao, lat, lng, historia, citacao, transcricao, destaque, status) values
  (1, 1, 'capela-de-nossa-senhora-das-dores', 'Capela de Nossa Senhora das Dores', 'Nossa Senhora das Dores', 'urbana', 'Centro', '1928', '15 de setembro', 'Colonial sertanejo', 'Bom', 'Dona Maria José', -7.8392, -38.0991, 'Capela de Nossa Senhora das Dores fica em Centro, na zona urbana de Triunfo. Segundo os moradores, a primeira missa no local foi celebrada por volta de 1928, quando famílias da comunidade se reuniram para erguer um pequeno templo dedicado a Nossa Senhora das Dores.
