insert into public.guardioes (id, capela_id, nome, citacao, transcricao, foto_url, destaque, status) values
  ('21a0e611-ae0e-ff69-f17e-7f3131e6058c', 1, 'Dona Maria José', 'A capela foi levantada pelas mãos da comunidade. Cada pedra tem o nome de uma família.', 'Eu nasci aqui perto e desde menina venho a essa capela. A gente limpava, enfeitava o altar com flor do mato e esperava o padre que vinha a cavalo uma vez por mês. A capela foi levantada pelas mãos da comunidade. Cada pedra tem o nome de uma família. Tem gente que vai embora para São Paulo, mas quando chega a festa todo mundo volta.', null, false, 'Publicado'),
  ('7a308a6f-34b0-09f8-b733-c038773a0c1a', 2, 'Seu Antônio Ferreira', 'Quando a chuva não vinha, era aqui que a gente rezava a novena. E ela vinha.', 'Eu nasci aqui perto e desde menina venho a essa capela. A gente limpava, enfeitava o altar com flor do mato e esperava o padre que vinha a cavalo uma vez por mês. Quando a chuva não vinha, era aqui que a gente rezava a novena. E ela vinha. Tem gente que vai embora para São Paulo, mas quando chega a festa todo mundo volta.', null, false, 'Publicado'),
  ('44ba2766-1a02-7cdc-3fb2-e497ad279762', 3, 'Dona Francisca', 'Minha mãe cuidou dessa chave por quarenta anos. Hoje sou eu quem abre a porta.', 'Eu nasci aqui perto e desde menina venho a essa capela. A gente limpava, enfeitava o altar com flor do mato e esperava o padre que vinha a cavalo uma vez por mês. Minha mãe cuidou dessa chave por quarenta anos. Hoje sou eu quem abre a porta. Tem gente que vai embora para São Paulo, mas quando chega a festa todo mundo volta.', 'img/c37.jpg', true, 'Publicado'),
  ('7dc0c1c5-0c60-1ad6-59fb-c776290679c0', 4, 'Dona Lourdes', 'Na festa do padroeiro o sítio todo se encontra. É a nossa maneira de agradecer.', 'Eu nasci aqui perto e desde menina venho a essa capela. A gente limpava, enfeitava o altar com flor do mato e esperava o padre que vinha a cavalo uma vez por mês. Na festa do padroeiro o sítio todo se encontra. É a nossa maneira de agradecer. Tem gente que vai embora para São Paulo, mas quando chega a festa todo mundo volta.', null, false, 'Publicado'),
  ('4c18ea84-c69e-acd1-ae45-872f9abebe76', 5, 'Seu Manoel', 'A capela foi levantada pelas mãos da comunidade. Cada pedra tem o nome de uma família.', 'Eu nasci aqui perto e desde menina venho a essa capela. A gente limpava, enfeitava o altar com flor do mato e esperava o padre que vinha a cavalo uma vez por mês. A capela foi levantada pelas mãos da comunidade. Cada pedra tem o nome de uma família. Tem gente que vai embora para São Paulo, mas quando chega a festa todo mundo volta.', null, false, 'Publicado'),
